#include "measurement.h"
#include <cmath>

bool calculateMeasurement(const MeasurementConfig&c,uint16_t a1,uint16_t a2,uint16_t a0,MeasurementResult&r){r.adc1Raw=a1;r.adc2Raw=a2;r.adc0Raw=a0;r.referenceResistance=c.referenceOhm;r.r0=c.r0Ohm;r.gaugeFactor=c.gaugeFactor;uint16_t sensor=c.adc1Role==RF430::ChannelRole::Sensor?a1:a2;uint16_t ref=c.adc1Role==RF430::ChannelRole::Reference?a1:a2;if(!sensor||!ref){r.error="zero ADC value";return false;}if(sensor==RF430::RAW_MAX||ref==RF430::RAW_MAX){r.error="ADC saturated";return false;}r.sensorResistance=c.referenceOhm*double(sensor)/double(ref);if(c.r0Ohm>0){r.deltaR=r.sensorResistance-c.r0Ohm;r.relativeDelta=r.deltaR/c.r0Ohm;r.strain=(r.relativeDelta/c.gaugeFactor)*1e6;}r.valid=isfinite(r.sensorResistance);return r.valid;}
bool MeasurementService::recoverAndConfigure(const MeasurementConfig&c){configured_=false;device_.resetReader();delay(30);if(!device_.detect())return false;if(!device_.applyConfig(c))return false;configured_=true;return true;}
bool MeasurementService::beginSingle(const MeasurementConfig&c){if(active_)return false;String e;if(!validateMeasurementConfig(c,e))return false;if(!device_.detected()&&!device_.detect()&&!recoverAndConfigure(c))return false;if(!configured_){if(!device_.applyConfig(c)&&!recoverAndConfigure(c))return false;configured_=true;}if(!device_.startSampling(c)){if(!recoverAndConfigure(c)||!device_.startSampling(c))return false;}active_=true;started_=millis();return true;}
bool MeasurementService::poll(const MeasurementConfig&c,MeasurementResult&r){if(!active_)return false;RF430::SamplingState s;uint8_t status;if(!device_.state(s,status)){if(millis()-started_>3000){active_=false;configured_=false;last_=MeasurementResult{};last_.timestampMs=millis();last_.error="RF430 communication timeout; recovery scheduled";r=last_;return true;}return false;}if(s==RF430::SamplingState::Error){active_=false;configured_=false;last_.error="RF430 sampling error status "+String(status,HEX);r=last_;return true;}uint32_t maxWait=22000;if(millis()-started_>maxWait){active_=false;configured_=false;last_.error="sampling timeout";r=last_;return true;}if(s!=RF430::SamplingState::DataReady)return false;uint8_t raw[8];uint16_t a1,a2,a0;last_=MeasurementResult{};last_.timestampMs=millis();if(!device_.readSample(c,a1,a2,a0,raw)){configured_=false;last_.error="sample block read failed; recovery scheduled";}else calculateMeasurement(c,a1,a2,a0,last_);active_=false;r=last_;return true;}
void MeasurementService::cancel(){if(active_)device_.stopSampling();active_=false;}
